"""specs_s200050.py - Sonnet-w2 family CB (generated by mkfamCB.py): BASE, 0x41e290 (heap object or 0) and 0x4ccbe0 record the SEH chain and the vtable word; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(base):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        o = rnd(c, 0x100)
        p = r.choice([0, rnd(c, 0x40), rnd(c, 0x40)])
        hook_rec(c, base, 3, ret=r.getrandbits(32), pop=12, this=True, side=_side(c, o))
        hook_rec(c, 0x41e290, 1, ret=p, pop=0, side=_side(c, o))
        hook_rec(c, 0x4ccbe0, 2, ret=r.getrandbits(32), pop=8, this=True, side=_side(c, o))
        return [o, r.getrandbits(32), r.getrandbits(32), r.getrandbits(32)]
    return gen


S(0x45a040, 'GUESS famCB 0x45a040', 'thiscall', None, ret='eax', gen=_mk(0x43e990), note='batch200050')
S(0x469f80, 'GUESS famCB 0x469f80', 'thiscall', None, ret='eax', gen=_mk(0x469da0), note='batch200050')
